86     // returns virtual pointer, writes physical parameter into arguments
87     void *allocate_dram(unsigned long len_in_bytes,
88                         unsigned long *physical_ptr) override {
89         py::gil_scoped_acquire acquire;
90 
91         // for now, we do uncacheable to keep things simple, memory accesses go
92         // straight to DRAM and
93         // thus would be coherent with the PL
94         py::module_ pynq = py::module_::import("pynq");
95         py::object buffer = pynq.attr("allocate")(
96             py::arg("shape") = py::make_tuple(len_in_bytes),
97             py::arg("dtype") = "u1");
98 
99         *physical_ptr = buffer.attr("physical_address").cast<unsigned long>();
100 
101         auto array = buffer.cast<py::array_t<uint8_t>>();
102         py::buffer_info info = array.request();
103         void *virtual_ptr = info.ptr;
104 
105         DramMap *dram_map = get_dram_map();
106         (*dram_map)[virtual_ptr] = buffer;
107 
108         return virtual_ptr;

